import assert from 'node:assert';
import { createState, step, collides, frame, WIDTH, HEIGHT } from '../game/neon.js';

// Mock canvas context
const mockCtx = {
  fillRect: () => {},
  arc: () => {},
  fill: () => {},
  beginPath: () => {},
  fillText: () => {},
};

test('D1 - Missing Deflection: Ball should bounce off the top of a brick', () => {
  const state = createState(1);
  const brick = state.bricks[0]; // top-left brick

  // Position ball so it's just about to hit the top of the first brick
  // Brick 0 is at BRICK_TOP = 48. Ball is moving DOWN.
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y - state.ball.r - 1;
  state.ball.vy = 100; // Moving DOWN
  state.ball.vx = 0;

  // In a real frame, the ball moves in step() then collision is checked in frame()
  // We simulate one frame's collision check.
  // Note: frame() modifies state.ball and state.bricks

  // Manually trigger the collision logic that's currently in frame()
  // Since we want to test if it BOUNCES, we look at the result.
  frame(mockCtx, state);

  assert.strictEqual(state.ball.vy, -100, 'Ball vy should be inverted after hitting top of brick');
});

test('D2 - Sticking: Ball should be pushed out of the brick', () => {
  const state = createState(1);
  const brick = state.bricks[0];

  // Position ball so it's already overlapping the top of the brick
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y - state.ball.r / 2; 
  state.ball.vy = 100;

  frame(mockCtx, state);

  assert.ok(state.ball.y <= brick.y - state.ball.r, 'Ball should be pushed above the brick');
});

test('D3 - Side Face Detection: Ball should bounce off the side of a brick', () => {
  const state = createState(1);
  const brick = state.bricks[0];

  // Position ball so it's about to hit the left side of the brick
  state.ball.x = brick.x - state.ball.r - 1;
  state.ball.y = brick.y + brick.h / 2;
  state.ball.vx = 100; // Moving RIGHT
  state.ball.vy = 0;

  frame(mockCtx, state);

  assert.strictEqual(state.ball.vx, -100, 'Ball vx should be inverted after hitting side of brick');
  assert.strictEqual(state.ball.vy, 0, 'Ball vy should not be changed when hitting the side');
});

test('D4 - Tunneling: Ball should not pass through brick at high speed', () => {
  const state = createState(1);
  const brick = state.bricks[0];

  // High speed: 1000 px/s. dt = 0.05s => 50px step.
  // Brick height = 20px.
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y - state.ball.r - 5; // Just above
  state.ball.vy = 1000; 

  // Simulate a step
  const dt = 0.05;
  step(state, dt); // ball.y becomes 48 - 7 - 5 + 50 = 86. Brick is at 48 to 68.

  // Now check collision in frame
  frame(mockCtx, state);

  // If it tunneled, brick.alive will still be true
  assert.strictEqual(brick.alive, false, 'Brick should be destroyed even if ball tunnels through it');
});

