// neon.test.js — PARTIAL coverage (on purpose).
//
// What is covered today: the collision primitive and a couple of physics
// bounces. What is NOT covered yet: score and combo (see ISSUES.md #5), nor
// level progression. This is a starting point for the testing work ahead, not
// a complete suite.
//
// Run: `node --test "game/**/*.test.js"`  (or `npm test`)

import { test } from 'node:test';
import assert from 'node:assert/strict';

import {
  collides,
  step,
  makeBricks,
  createState,
  BRICK_ROWS,
  BRICK_COLS,
  WIDTH,
  frame,
} from './neon.js';

const mockCtx = {
  fillRect: () => {},
  arc: () => {},
  fill: () => {},
  beginPath: () => {},
  fillText: () => {},
};

test('collides: clear overlap detected', () => {
  const ball = { x: 100, y: 100, r: 8 };
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), true);
});

test('collides: ball clearly away => no collision', () => {
  const ball = { x: 300, y: 300, r: 8 };
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), false);
});

test('collides: edge contact (radius) detected', () => {
  const ball = { x: 85, y: 100, r: 8 }; // right edge of the ball at 93 > 90
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), true);
});

test('step: bounce off the left wall', () => {
  const state = createState(1);
  state.ball = { x: 2, y: 200, r: 7, vx: -300, vy: 0 };
  step(state, 1 / 60);
  assert.ok(state.ball.vx > 0, 'horizontal velocity should flip to the right');
});

test('step: ball exiting through the bottom => lost', () => {
  const state = createState(1);
  state.ball = { x: 320, y: belowField(), r: 7, vx: 0, vy: 400 };
  const lost = step(state, 1 / 60);
  assert.equal(lost, true);
});

test('makeBricks: full, all-alive grid at start', () => {
  const bricks = makeBricks(1);
  assert.equal(bricks.length, BRICK_ROWS * BRICK_COLS);
  assert.ok(bricks.every((b) => b.alive));
  assert.ok(bricks.every((b) => b.x >= 0 && b.x + b.w <= WIDTH));
});

// --- New Playtest-driven tests ---

test('D1 - Missing Deflection: Ball should bounce off the top of a brick', () => {
  const state = createState(1);
  const brick = state.bricks[0]; 
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y - state.ball.r - 1;
  state.ball.vy = 100; 
  state.ball.vx = 0;
  frame(mockCtx, state);
  assert.strictEqual(state.ball.vy, -100, 'Ball vy should be inverted after hitting top of brick');
});

test('D2 - Sticking: Ball should be pushed out of the brick', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y - state.ball.r / 2; 
  state.ball.vy = 100;
  frame(mockCtx, state);
  assert.ok(state.ball.y <= brick.y - state.ball.r, 'Ball should be pushed above the brick');
});

test('D3 - Side Face Detection: Ball should bounce off the side of a brick', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball.x = brick.x - state.ball.r - 1;
  state.ball.y = brick.y + brick.h / 2;
  state.ball.vx = 100;
  state.ball.vy = 0;
  frame(mockCtx, state);
  assert.strictEqual(state.ball.vx, -100, 'Ball vx should be inverted after hitting side of brick');
  assert.strictEqual(state.ball.vy, 0, 'Ball vy should not be changed when hitting the side');
});

test('D4 - Tunneling: Ball should not pass through brick at high speed', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y - state.ball.r - 5;
  state.ball.vy = 1000; 
  step(state, 0.05);
  frame(mockCtx, state);
  assert.strictEqual(brick.alive, false, 'Brick should be destroyed even if ball tunnels through it');
});

function belowField() {
  return 500;
}

edits.newText:
// True if the ball (circle approximated by its box) overlaps the brick.
export function collides(ball, brick) {
  return (
    ball.x + ball.r > brick.x &&
    ball.x - ball.r < brick.x + brick.w &&
    ball.y + ball.r > brick.y &&
    ball.y - ball.r < brick.y + brick.h
  );
}

// Resolves the collision between the ball and a brick.
// Returns true if the ball's trajectory was changed.
export function resolveCollision(ball, brick) {
  // Find the axis of least penetration
  const overlapX = Math.min(ball.x + ball.r - brick.x, brick.x + brick.w - (ball.x - ball.r));
  const overlapY = Math.min(ball.y + ball.r - brick.y, brick.y + brick.h - (ball.y - ball.r));

  if (overlapX < overlapY) {
    // Horizontal collision
    if (ball.x < brick.x) {
      ball.x = brick.x - ball.r;
    } else {
      ball.x = brick.x + brick.w + ball.r;
    }
    ball.vx = -Math.sign(ball.vx) * Math.abs(ball.vx); // just flip sign
    // wait, the simple flip might be enough, but let's use a more explicit one
    // ball.vx = -ball.vx;
    return true;
  } else {
    // Vertical collision
    if (ball.y < brick.y) {
      ball.y = brick.y - ball.r;
    } else {
      ball.y = brick.y + brick.h + ball.r;
    }
    ball.vy = -ball.vy;
    return true;
  }
}

