// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls, the paddle, and the bricks.
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;

  const oldX = ball.x;
  const oldY = ball.y;

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

  // --- Brick collisions (with tunneling prevention) ---
  // We divide the movement into small steps to ensure we don't jump over bricks.
  const dist = Math.sqrt((ball.x - oldX) ** 2 + (ball.y - oldY) ** 2);
  const subSteps = Math.ceil(dist / BALL_R);

  for (let i = 1; i <= subSteps; i++) {
    const checkX = oldX + (ball.x - oldX) * (i / subSteps);
    const checkY = oldY + (ball.y - oldY) * (i / subSteps);
    const checkBall = { ...ball, x: checkX, y: checkY };

    for (const brick of state.bricks) {
      if (!brick.alive) continue;
      if (collides(checkBall, brick)) {
        brick.alive = false;
        state.combo += 1;
        state.score += scoreForBrick(brick, state.combo);
        resolveCollision(ball, brick);
      }
    }
  }

  // Side walls
  if (ball.x - ball.r < 0) {
    ball.x = ball.r;
    ball.vx = Math.abs(ball.vx);
  } else if (ball.x + ball.r > WIDTH) {
    ball.x = WIDTH - ball.r;
    ball.vx = -Math.abs(ball.vx);
  }

  // Ceiling
  if (ball.y - ball.r < 0) {
    ball.y = ball.r;
    ball.vy = Math.abs(ball.vy);
  }

  // Paddle
  if (
    ball.vy > 0 &&
    ball.y + ball.r >= paddle.y &&
    ball.y + ball.r <= paddle.y + paddle.h &&
    ball.x >= paddle.x &&
    ball.x <= paddle.x + paddle.w
  ) {
    ball.y = paddle.y - ball.r;
    ball.vy = -Math.abs(ball.vy);
    const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
    ball.vx = ballSpeed(state.level) * 0.6 * hit;
    state.combo = 0;
  }

  // Exit through the bottom: ball lost
  if (ball.y - ball.r > HEIGHT) {
    return true;
  }
  return false;
}

